import {estimateSource,workedEstimate,estimateValue,estimateRange,estimatesView,keepEstimate} from './courier-estimates-core.mjs';
import {hearButton} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x),same=(a,b)=>a===null&&b===null||!!a&&!!b&&a.start===b.start&&a.rate===b.rate;
const num=n=>String(Object.is(n,-0)?0:n),unit=(n,word)=>`${num(n)} ${word}${Math.abs(n)===1?'':'s'}`;
const signed=n=>n>0?`+${num(n)}`:n<0?`−${num(-n)}`:'0';
const btn=(attr,label,{disabled=false,pressed=null}={})=>`<button type="button" ${attr}${disabled?' disabled':''}${pressed===null?'':` aria-pressed="${pressed}"`}>${esc(label)}</button>`;
const pages=['Records','Try a line','Use an estimate'];
const freshUI=()=>({page:0,table:false,worked:false,step:0,gaps:false,rise:false});
let visit=null,generation=0;
export function resetEstimateVisit(){visit=null;generation++;}
function session(state,owner){if(!visit||visit.state!==state||visit.owner!==owner)visit={state,owner,slots:new Map(),keptUI:new Map(),current:null,notice:''};return visit;}
function current(s,state){
 if(!s.current)return null;
 if(s.current.kind==='draft'){const slot=s.slots.get(s.current.key);return slot?{...slot,mutable:true,key:s.current.key}:null;}
 const row=estimatesView(state).items.find(i=>i.id===s.current.id&&i.readable);
 if(!row)return null;if(!s.keptUI.has(row.id))s.keptUI.set(row.id,freshUI());
 return {work:row.raw,ui:s.keptUI.get(row.id),mutable:false,id:row.id};
}
function newWork(source){return {source,line:{start:2,rate:2},pin:null,recordId:source.rows[0].id,requestX:source.requests[0],result:null,support:{worked:false,gaps:false,rise:false,narration:false}};}
const values=w=>({row:w.source.rows.find(r=>r.id===w.recordId),estimate:estimateValue(w.line,w.source.rows.find(r=>r.id===w.recordId).x)});
const equation=line=>`estimate = ${num(line.rate)} × blocks + ${num(line.start)}`;
function sourceTable(source,selectable=false){return `<table><caption>${esc(source.title)}</caption><thead><tr><th scope="col">Record</th><th scope="col">Route · model blocks</th><th scope="col">Recorded time · minutes</th></tr></thead><tbody>${source.rows.map((r,i)=>`<tr><th scope="row">${selectable?btn(`data-ce-record="${esc(r.id)}"`,`Record ${i+1}`):i+1}</th><td>${num(r.x)}</td><td>${num(r.y)}</td></tr>`).join('')}</tbody></table>`;}
function sourceFold(w,ui){return `<details data-ce-fold="table"${ui.table?' open':''}><summary>Records and source</summary><p>${esc(w.source.origin)}</p><p>${esc(w.source.notice)}</p><p>${esc(w.source.context)}</p>${sourceTable(w.source)}</details>`;}
function rangeText(source,x){const kind=estimateRange(source,x);return kind==='outside'?'This length is outside the recorded lengths. The line gives a number, but these records give less support here.':kind==='edge'?"This length is at the edge of the recorded lengths. The line’s value is still an estimate, not a new recorded trip.":kind==='observed'?'Even at a recorded length, this line estimates a different trip. It does not replace that record.':'This length is between the recorded lengths. It is still an estimate, not a recorded trip.';}
function resultState(w){if(!w.result)return 'absent';if(w.result.x!==w.requestX)return 'request';if(!same(w.result.line,w.line))return 'line';if(!same(w.result.pin,w.pin))return 'pin';return 'current';}
// Axis rectangle is intentionally simple and independently checked in the browser.
const at=(source,x,y)=>({x:64+392*x/source.axes.x.max,y:292-268*y/source.axes.y.max});
function ticks(max){const step=Math.max(1,Math.ceil(max/5)),v=[];for(let n=0;n<max;n+=step)v.push(n);v.push(max);return v;}
function plot(w,ui,{example=false}={}){
 const source=w.source,xMax=source.axes.x.max,yMax=source.axes.y.max;
 const min=Math.min(...source.rows.map(r=>r.x)),max=Math.max(...source.rows.map(r=>r.x));
 const line=(l,attrs,cls)=>{const a=at(source,0,l.start),b=at(source,xMax,estimateValue(l,xMax));return `<line ${attrs} class="${cls}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`;};
 const grid=ticks(xMax).map(x=>{const p=at(source,x,0);return `<path d="M${p.x} 24V292"/><text x="${p.x}" y="320" text-anchor="middle">${x}</text>`;}).join('')+ticks(yMax).map(y=>{const p=at(source,0,y);return `<path d="M64 ${p.y}H456"/><text x="54" y="${p.y}" text-anchor="end" dominant-baseline="middle">${y}</text>`;}).join('');
 const circles=source.rows.map((r,i)=>{const p=at(source,r.x,r.y);return `<circle ${example?'':`data-ce-observation="${esc(r.id)}"`} class="ce-dot${r.id===w.recordId?' ce-selected':''}" cx="${p.x}" cy="${p.y}" r="${r.id===w.recordId?7:5}"><title>Record ${i+1}: ${unit(r.x,'block')}, ${unit(r.y,'minute')}</title></circle>`;}).join('');
 const row=source.rows.find(r=>r.id===w.recordId),point=at(source,row.x,row.y),estimated=at(source,row.x,estimateValue(w.line,row.x));
 let predictions='';if(!example&&resultState(w)==='current')for(const [key,l,label] of [['current',w.result.line,'C'],['pin',w.result.pin,'P']])if(l){const y=estimateValue(l,w.result.x),p=at(source,w.result.x,y);predictions+=`<polygon data-ce-diamond="${key}" data-x="${w.result.x}" data-y="${y}" class="ce-diamond ${key==='pin'?'ce-pinned':''}" points="${p.x},${p.y-7} ${p.x+7},${p.y} ${p.x},${p.y+7} ${p.x-7},${p.y}"/><text class="ce-marker-label" x="${p.x+(key==='pin'?12:-12)}" y="${p.y-10}" text-anchor="middle">${label}</text>`;}
 let rise='';if(ui.rise){const run=Math.min(2,xMax),p=at(source,0,w.line.start),q=at(source,run,w.line.start),r=at(source,run,estimateValue(w.line,run));rise=`<path data-ce-rise-path d="M${p.x} ${p.y}H${q.x}V${r.y}" class="ce-rise-path"/>`;}
 const desc=`${source.axes.x.label}: 0 to ${xMax}. ${source.axes.y.label}: 0 to ${yMax}. ${source.rows.length} recorded trips stay fixed. Current ${equation(w.line)}. Selected record ${unit(row.x,'block')}, ${unit(row.y,'minute')}; estimate ${unit(estimateValue(w.line,row.x),'minute')}.`;
 return `<figure class="ce-figure"><p class="ce-axis">Y · ${esc(source.axes.y.label)}</p><svg ${example?'data-ce-example-plot':'data-ce-plot'} viewBox="0 0 480 340" role="img" aria-label="${esc(desc)}"><g class="ce-outside"><rect x="64" y="24" width="${at(source,min,0).x-64}" height="268"/><rect x="${at(source,max,0).x}" y="24" width="${456-at(source,max,0).x}" height="268"/></g><g class="ce-grid">${grid}</g><path class="ce-axes" d="M64 24V292H456"/>${w.pin?line(w.pin,'','ce-line ce-pinned'):''}${line(w.line,example?'':'data-ce-line','ce-line')}${rise}<line ${example?'':'data-ce-gap'} class="ce-gap" x1="${point.x}" y1="${point.y}" x2="${estimated.x}" y2="${estimated.y}"/>${circles}${predictions}</svg><p class="ce-axis">X · ${esc(source.axes.x.label)}</p><figcaption>Circle: recorded trip. Solid line: current estimate.${w.pin?' Dashed line: pinned estimate.':''} Shaded: outside the recorded lengths.${predictions?' Diamond C: current estimate. Diamond P: pinned estimate, when present.':''}</figcaption></figure>`;
}
function selected(w){const {row,estimate}=values(w),gap=row.y-estimate;return `<section class="ce-gap-card"><h3>Record ${w.source.rows.findIndex(r=>r.id===w.recordId)+1} · ${unit(row.x,'model block')}</h3><p>Recorded: <strong>${unit(row.y,'minute')}</strong>. Line estimate: <strong>${unit(estimate,'minute')}</strong>.</p><p data-ce-gap-text>Recorded minus estimated: <strong>${signed(gap)} ${Math.abs(gap)===1?'minute':'minutes'}</strong>.</p><p>${gap>0?'This record is above the line: the trip took longer than this line estimates.':gap<0?'This record is below the line: the trip took less time than this line estimates.':"This record agrees with the line at this length. That doesn’t make every other record agree."}</p>${w.pin?`<p>Pinned line estimate: ${unit(estimateValue(w.pin,row.x),'minute')}.</p>`:''}</section>`;}
function rules(w){return `<div class="ce-rules"><p><strong>Current line · ${esc(equation(w.line))}</strong></p><p>Rate: ${unit(w.line.rate,'minute')} per block · start: ${unit(w.line.start,'minute')} at zero blocks.</p>${w.pin?`<p>Pinned line · ${esc(equation(w.pin))}</p>`:''}</div>`;}
function controls(w){return `<div class="ce-controls">${[['start','Start · minutes at zero blocks',w.source.starts,'start-value'],['rate','Rate · minutes per block',w.source.rates,'rate']].map(([key,label,choices,attr])=>`<div><label for="ce-${attr}">${label}</label><div class="ce-stepper">${btn(`data-ce-change="${key}" data-ce-delta="-1" aria-label="Decrease ${key}"`,'−',{disabled:choices.indexOf(w.line[key])===0})}<select id="ce-${attr}" data-ce-${attr}>${choices.map(v=>`<option value="${v}"${v===w.line[key]?' selected':''}>${v}</option>`).join('')}</select>${btn(`data-ce-change="${key}" data-ce-delta="1" aria-label="Increase ${key}"`,'+',{disabled:choices.indexOf(w.line[key])===choices.length-1})}</div></div>`).join('')}</div>`;}
function recordButtons(w){return `<div class="ce-records" role="group" aria-label="Choose a recorded trip">${w.source.rows.map((r,i)=>btn(`data-ce-record="${esc(r.id)}" aria-label="Record ${i+1}, ${unit(r.x,'block')}, ${unit(r.y,'minute')}"`,`Record ${i+1}`,{pressed:r.id===w.recordId})).join('')}</div>`;}
function allGaps(w){return `<table><caption>All gaps · recorded times, estimates and gaps are in minutes</caption><thead><tr><th>Record · blocks</th><th>Recorded</th><th>Estimated</th><th>Gap</th></tr></thead><tbody>${w.source.rows.map((r,i)=>{const e=estimateValue(w.line,r.x);return `<tr><th scope="row">${i+1} · ${unit(r.x,'block')}</th><td>${r.y}</td><td>${num(e)}</td><td>${signed(r.y-e)}</td></tr>`;}).join('')}</tbody></table>`;}
function worked(w,ui){const e=workedEstimate(w.source);if(!e)return '<p>The earlier example stays in your notes. This model is still open.</p>';if(!ui.worked)return btn('data-ce-worked','Show a different example');const ex={source:{...w.source,axes:e.axes,rows:e.rows},line:e.line,pin:null,recordId:e.rows[Math.min(ui.step,e.rows.length-1)].id,result:null};return `<section class="ce-example"><h3 id="ce-example" tabindex="-1">Different example</h3>${plot(ex,{rise:false},{example:true})}<p>${esc(e.steps[ui.step])}</p><div class="ce-actions">${btn('data-ce-step="-1"','Previous step',{disabled:ui.step===0})}${btn('data-ce-step="1"','Next step',{disabled:ui.step===e.steps.length-1})}${btn('data-ce-worked','Close example')}</div>${sourceTable(ex.source)}</section>`;}
function result(w,mutable){const state=resultState(w);if(state==='absent')return '<p>No estimate used yet.</p>';const r=w.result;if(state==='request')return `<p>${mutable?`Your estimate was for ${unit(r.x,'model block')}. Choose that length or use this line for this one.`:`Your estimate was for ${unit(r.x,'model block')}. Try this model again to choose another length.`}</p>`;return `<section class="ce-result" aria-label="Used estimate"><h3>Estimate for ${unit(r.x,'model block')}</h3><p>${num(r.line.rate)} × ${num(r.x)} + ${num(r.line.start)} = <strong>${unit(estimateValue(r.line,r.x),'minute')}</strong>.</p>${r.pin?`<p>Pinned line estimate: ${r.pin.rate} × ${r.x} + ${r.pin.start} = ${unit(estimateValue(r.pin,r.x),'minute')}.</p>`:''}<p>${esc(rangeText(w.source,r.x))}</p>${state==='line'||state==='pin'?`<p>${state==='line'?'Your line has changed.':'Your comparison has changed.'} ${mutable?'Use this line to update the estimate.':'Try this model again to update the estimate.'}</p>`:''}</section>`;}
function turn(c){const {work:w,ui,mutable}=c;
 if(ui.page===0)return `<h2 id="ce-turn-heading" tabindex="-1">Two numbers, one trip</h2><p>Route length goes across; recorded minutes go up. Every circle is one record.</p>${sourceTable(w.source)}${mutable?worked(w,ui):''}`;
 if(ui.page===1)return `<h2 id="ce-turn-heading" tabindex="-1">Change the line, keep the records</h2><p>Try changing the start. Then choose a record and compare its time with the line’s estimate.</p>${mutable?controls(w):''}<p>${w.source.rows.some(r=>r.x===0)?"This source includes a zero-block record. The start is the line’s value there; compare it with the record.":'The start is this line’s value at zero blocks. None of these trips was zero blocks long.'}</p>${mutable?recordButtons(w):''}${selected(w)}${mutable?`<div class="ce-actions">${btn('data-ce-pin',w.pin?'Replace pinned line':'Pin this line for comparison')}${w.pin?btn('data-ce-unpin','Remove comparison'):''}${btn('data-ce-rise',ui.rise?'Hide rate steps':'Show rate steps')}${btn('data-ce-gaps',ui.gaps?'Hide all gaps':'Show all gaps')}</div>`:''}${w.pin?'<p>The dashed line keeps your earlier start and rate. Neither line changes the recorded trips.</p>':''}${ui.rise?`<p>Across ${unit(Math.min(2,w.source.axes.x.max),'model block')}, ${w.line.rate===0?'the change is 0 minutes. The line is level.':`this line changes by ${unit(Math.min(2,w.source.axes.x.max)*w.line.rate,'minute')}. Its rate is ${unit(w.line.rate,'minute')} per block.`}</p>`:''}`;
 return `<h2 id="ce-turn-heading" tabindex="-1">A new errand</h2><p>Choose a route length, then use your current line to estimate its time.</p>${mutable?`<div class="ce-actions">${w.source.requests.map(x=>btn(`data-ce-request="${x}"`,unit(x,'model block'),{pressed:w.requestX===x})).join('')}${btn('data-ce-use','Use this line')}</div>`:`<p>Selected request: ${unit(w.requestX,'model block')}.</p>`}${result(w,mutable)}<h3>Talk or write on paper</h3><ul>${w.source.teaching.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><p>These records show a pattern, not why it happened. They don’t show that changing a route’s length alone would change its time by this rate.</p><p>Try the other records. Would you keep the same line, or change it? You can keep both models.</p>`;
}
function chooser(s,state){const v=estimatesView(state);return `<section><h2 id="ce-chooser" tabindex="-1">Which records shall we try?</h2><p>Dot has some trip records and a new errand. Can a line help estimate the time?</p><p>“A rule can be exact,” says Dot. “My trip records don’t all follow one exact rule. Let’s try a line without changing the records.”</p><div class="ce-source-choices">${btn('data-ce-start="orchard"','Start Orchard rounds')}${btn('data-ce-start="library"','Start Library rounds')}</div>${s.slots.size?`<h3>Unkept models in this visit</h3><div class="ce-actions">${[...s.slots].map(([key,slot])=>btn(`data-ce-resume="${esc(key)}"`,`Continue ${slot.work.source.title}`)).join('')}</div>`:''}<h3>Earlier kept models</h3>${v.items.length?`<div class="ce-source-choices">${v.items.map(i=>i.readable?btn(`data-ce-open="${esc(i.id)}"`,`${i.raw.source.title} · kept model ${i.index+1} · ${equation(i.raw.line)}`):'<p>Earlier model retained · its original stays in your notes.</p>').join('')}</div>`:'<p>No kept models yet.</p>'}${v.status==='unsupported'?'<p>Earlier estimates are kept in your notes. This format cannot accept another model here.</p>':''}</section>`;}
export function estimatePage(state,owner){
 const s=session(state,owner),c=current(s,state);
 return `<div class="ce-page" data-ce-root${c&&!c.mutable?' data-ce-kept':''}><header><a href="#learn/math">Back to math explorations</a><h1>Courier Estimates</h1><p>Made-up courier records. These numbers are invented for this workbench. They are not real delivery times or promises.</p></header>${c?`<p class="ce-source-name">${esc(c.work.source.title)} · ${c.mutable?'Changes stay in this visit until you keep a model. Leaving this place clears unkept changes.':'This kept model stays as it was. Try it again to make another version.'}</p><nav class="ce-tabs" aria-label="Workbench pages">${pages.map((p,i)=>btn(`data-ce-page="${i}"`,p,{pressed:c.ui.page===i})).join('')}</nav>${rules(c.work)}<div class="ce-workspace"><div>${plot(c.work,c.ui)}</div><section class="ce-turn" data-ce-turn>${turn(c)}</section></div>${c.ui.page===1&&c.ui.gaps?`<section class="ce-all-gaps">${allGaps(c.work)}<p>Look at all the gaps. A line through one record can still miss the rest. The same count above and below does not tell us how large the gaps are.</p></section>`:''}${sourceFold(c.work,c.ui)}<div class="ce-actions ce-page-actions">${btn(`data-ce-page="${c.ui.page-1}"`,'Previous',{disabled:c.ui.page===0})}${btn(`data-ce-page="${c.ui.page+1}"`,'Next',{disabled:c.ui.page===2})}${c.mutable?`${btn('data-ce-keep','Keep this model')}${hearButton('','Hear this turn').replace('<button','<button data-ce-hear')}`:btn(`data-ce-again="${esc(c.id)}"`,'Try this model again')}${btn('data-ce-choose','Choose records')}</div>`:chooser(s,state)}<p id="ce-status" role="status" tabindex="-1" class="ce-status${s.notice?'':' sr-only'}">${esc(s.notice)}</p><footer class="ce-actions"><a href="#learn/math/paired">Paired points</a><a href="#learn/math">Signed rates and linear equations</a><a href="#notes">Grown-up notes</a></footer></div>`;
}
export function bindEstimates(state,ctx){
 const root=document.querySelector('[data-ce-root]');if(!root)return;const owner=ctx.explorerId(),s=session(state,owner),binding=++generation;
 const live=node=>root.isConnected&&node?.isConnected&&generation===binding&&visit===s&&location.hash==='#learn/math/estimates'&&ctx.notebook()===state&&ctx.explorerId()===owner&&ctx.isActive?.()!==false;
 const redraw=(focus='#ce-turn-heading')=>{ctx.stopSpeech?.();ctx.stopSound?.();ctx.render();let target=document.querySelector(focus);if(target?.disabled&&target.dataset.ceChange)target=document.querySelector(target.dataset.ceChange==='start'?'[data-ce-start-value]':'[data-ce-rate]');if(!target||target.disabled)target=document.querySelector('#ce-turn-heading');target?.focus({preventScroll:true});};
 const each=(selector,fn)=>root.querySelectorAll(selector).forEach(node=>node.addEventListener('click',()=>{if(live(node)&&!node.disabled)fn(node);}));
 const active=()=>current(s,state),editable=fn=>{const c=active();if(c?.mutable){s.notice='';fn(c);}};
 each('[data-ce-start]',b=>{const key=`chooser:${b.dataset.ceStart}`;if(!s.slots.has(key)){const source=estimateSource(b.dataset.ceStart);if(!source)return;s.slots.set(key,{work:newWork(source),ui:freshUI()});}s.current={kind:'draft',key};s.notice='';redraw();});
 each('[data-ce-resume]',b=>{if(s.slots.has(b.dataset.ceResume)){s.current={kind:'draft',key:b.dataset.ceResume};s.notice='';redraw();}});
 each('[data-ce-open]',b=>{if(estimatesView(state).items.some(i=>i.id===b.dataset.ceOpen&&i.readable)){s.current={kind:'kept',id:b.dataset.ceOpen};s.notice='';redraw();}});
 each('[data-ce-again]',b=>{const row=estimatesView(state).items.find(i=>i.id===b.dataset.ceAgain&&i.readable);if(!row)return;const key=`again:${row.id}`;if(!s.slots.has(key)){const {source,line,pin,recordId,requestX,result,support}=row.raw;s.slots.set(key,{work:clone({source,line,pin,recordId,requestX,result,support}),ui:freshUI()});}s.current={kind:'draft',key};s.notice='';redraw();});
 each('[data-ce-choose]',()=>{s.current=null;s.notice='';redraw('#ce-chooser');});
 each('[data-ce-page]',b=>{const c=active(),page=Number(b.dataset.cePage);if(c&&Number.isInteger(page)&&page>=0&&page<=2){c.ui.page=page;redraw();}});
 function changeLine(key,value,focus){editable(c=>{const choices=key==='start'?c.work.source.starts:c.work.source.rates;if(!choices.includes(value))return;c.work.line[key]=value;redraw(focus);});}
 for(const [selector,key] of [['[data-ce-start-value]','start'],['[data-ce-rate]','rate']])root.querySelector(selector)?.addEventListener('change',e=>{if(live(e.target))changeLine(key,Number(e.target.value),selector);});
 each('[data-ce-change]',b=>{const c=active();if(!c?.mutable)return;const key=b.dataset.ceChange,choices=key==='start'?c.work.source.starts:c.work.source.rates,index=choices.indexOf(c.work.line[key])+Number(b.dataset.ceDelta);if(index>=0&&index<choices.length)changeLine(key,choices[index],`[data-ce-change="${key}"][data-ce-delta="${b.dataset.ceDelta}"]`);});
 each('[data-ce-record]',b=>editable(c=>{if(c.work.source.rows.some(r=>r.id===b.dataset.ceRecord)){c.work.recordId=b.dataset.ceRecord;redraw(`[data-ce-record="${CSS.escape(b.dataset.ceRecord)}"]`);}}));
 each('[data-ce-pin]',()=>editable(c=>{c.work.pin=clone(c.work.line);redraw('[data-ce-pin]');}));
 each('[data-ce-unpin]',()=>editable(c=>{c.work.pin=null;redraw('[data-ce-pin]');}));
 each('[data-ce-request]',b=>editable(c=>{const x=Number(b.dataset.ceRequest);if(c.work.source.requests.includes(x)){c.work.requestX=x;redraw(`[data-ce-request="${x}"]`);}}));
 each('[data-ce-use]',()=>editable(c=>{c.work.result={x:c.work.requestX,line:clone(c.work.line),pin:clone(c.work.pin)};redraw('[data-ce-use]');}));
 for(const key of ['gaps','rise'])each(`[data-ce-${key}]`,()=>editable(c=>{c.ui[key]=!c.ui[key];if(c.ui[key])c.work.support[key]=true;redraw(`[data-ce-${key}]`);}));
 each('[data-ce-worked]',()=>editable(c=>{if(workedEstimate(c.work.source)){c.ui.worked=!c.ui.worked;if(c.ui.worked)c.work.support.worked=true;redraw(c.ui.worked?'#ce-example':'[data-ce-worked]');}}));
 each('[data-ce-step]',b=>editable(c=>{const e=workedEstimate(c.work.source),n=c.ui.step+Number(b.dataset.ceStep);if(e&&n>=0&&n<e.steps.length){c.ui.step=n;redraw('#ce-example');}}));
 root.querySelectorAll('[data-ce-fold]').forEach(node=>node.addEventListener('toggle',()=>{if(live(node)){const c=active();if(c){c.ui.table=node.open;ctx.stopSpeech?.();}}}));
 each('[data-ce-keep]',()=>editable(c=>{const id=keepEstimate(state,c.work,{canExport:ctx.canExport});if(!id){const v=estimatesView(state);s.notice=v.status==='unsupported'?'Earlier estimates are kept in your notes. This format cannot accept another model here.':!v.canKeep?'Your earlier models are safe. This notebook cannot keep another model here. You can keep exploring in this visit and download your notes.':'This model could not be kept. Nothing was changed. Your line is still here; open Grown-up notes to download your work.';redraw('#ce-status');return;}s.slots.delete(c.key);s.keptUI.set(id,{...c.ui,worked:false,gaps:false,rise:false});s.current={kind:'kept',id};const saved=ctx.save?.();s.notice=saved?.enabled===false?'Model kept for this session. Saving on this device is off.':saved?.ok===false?'This model is in this session, but it could not be saved on this device. Download your notes.':'Model kept. The records and this line stay together.';redraw('#ce-status');}));
 root.addEventListener('click',event=>{const hear=event.target.closest?.('[data-ce-hear]');if(!hear)return;const c=active();if(!live(hear)||!c?.mutable){event.preventDefault();event.stopImmediatePropagation();return;}c.work.support.narration=true;let words=[c.work.source.title,c.work.source.notice,equation(c.work.line),root.querySelector('[data-ce-turn]')?.innerText||''];if(c.ui.table)words.push(c.work.source.origin,c.work.source.context);hear.dataset.speak=words.join('. ').replaceAll('−','minus ');},true);
}

// Adult Notes only: no child route calls this function.
export function estimateNotes(state){
 if(!Object.hasOwn(state,'courierEstimates'))return '';
 try{const v=estimatesView(state);return `<details class="ce-notes"><summary>Courier Estimates · kept models</summary><p>Supported model exploration with invented records. Kept models retain their own source, line, optional comparison, used estimate and disclosed help. These are not independent-response checks, a level or real predictions. Spoken and paper explanations are not recorded. Unkept changes are session-only.</p>${v.items.filter(i=>i.readable).map(i=>`<p>${esc(i.raw.source.title)} · ${esc(i.id)} · ${esc(equation(i.raw.line))}. Example opened: ${i.raw.support.worked}; all gaps: ${i.raw.support.gaps}; rate guide: ${i.raw.support.rise}; narration requested: ${i.raw.support.narration}.</p>`).join('')}<details><summary>Original estimate notes, including retained unreadable values</summary><pre>${esc(JSON.stringify(state.courierEstimates,null,2))}</pre></details></details>`;}catch{return '<p>Earlier estimate notes retained unchanged in the download.</p>';}
}
// End adult estimate notes.
